          </div>
        </div>
        <div class="book-stack">
          {/* <img class="catLookingUp" src={catLookingUp} alt="Purple Cat" /> */}
        </div>
      </div>
      <div class="shelf-wood" style={{ zIndex: 2 }}></div>
      {/* Shelf 5*/}
      <div class="shelf">
        <div class="book-stack">
          <div
            class="book"
            style={{ backgroundColor: "var(--light)", width: "60%" }}
            onClick={() => handleClickBook("Heidi.txt")}
          >
            <i>Heidi</i>
          </div>
          <div
            class="book"
            style={{ backgroundColor: "var(--dusty)", width: "80%" }}
            onClick={() => handleClickBook("Sherlock Holmes.txt")}
          >
            <i>Sherlock Holmes</i>
          </div>
          <div
            class="book"
            style={{ backgroundColor: "var(--bright)", width: "80%" }}
            onClick={() => handleClickBook("Carmilla.txt")}
          >
            <i>Carmilla</i>
          </div>
          <div
            class="book"
            style={{ backgroundColor: "var(--dusty)", width: "90%" }}
            onClick={() => handleClickBook("Black Beauty.txt")}
          >
            <i>Black Beauty</i>
          </div>
        </div>
        <div class="book-stack-right">
          <div
            class="upright-book"
            style={{
              backgroundColor: "var(--light)",
              height: "60%",
              marginRight: "18px",
              transform: "rotate(20deg)",
            }}
          ></div>
          <div
            class="upright-book"
            style={{ backgroundColor: "var(--dusty)", height: "70%" }}
          ></div>
          <div
            class="upright-book"
            style={{ backgroundColor: "var(--light)", height: "80%" }}
          ></div>
        </div>
      </div>
      <div class="shelf-wood" style={{ height: 2 }}></div>
    </div>
  );
};

